+                    // creating a new segment automatically registers it with the segments store
+                    allSegments.add(new WriteBufferSegmentWithDbFallback(dbSegment));
+                    dbIndex++;
+                } else if (dbSegmentId < bufferSegmentId) {
+                    allSegments.add(bufferSegment);
+                    bufferIndex++;
+                } else {
+                    allSegments.add(bufferSegment);
+                    dbIndex++;
+                    bufferIndex++;
+                }
+            }
