+
+            KafkaFutureImpl<Long> waiter = new KafkaFutureImpl<>();
+            waiter.thenApply((KafkaFuture.BaseFunction<Long, Void>) now -> {
+                try {
+                    callable.call();
+                } catch (Throwable e) {
+                    e.printStackTrace();
+                }
+                return null;
+            });
+            addWaiter(delayMs, period, waiter);
+            return null;
+        }
