+    @Test
+    public void testValidator() {
+        ShareGroupAutoOffsetResetStrategy.Validator validator = new ShareGroupAutoOffsetResetStrategy.Validator();
+        assertDoesNotThrow(() -> validator.ensureValid("test", "earliest"));
